        ["Arrangement error:"] = "Arrangementfehler:",
        ["Assign MIDI tracks in Party-Roster Track Assignments below, then press SET PARTY TRACKS."] = "Weise den Barden unten unter Gruppen-Spurzuweisungen MIDI-Spuren zu und drücke SPUREN FESTLEGEN.",
